#!/usr/bin/env bash
# run_kvtest.sh — launch the mooncake_kvtest C++ binary for kvtest scenarios
# on the server (pod or bare-metal node).
#
# Usage: run_kvtest.sh LOG_FILE CONFIG_JSON [BINARY]
#   LOG_FILE    stdout of the binary (its glog stream goes to $LOG_FILE.glog)
#   CONFIG_JSON per-instance kvtest config generated by benchmark.py; the
#               __UB_DEVICE__ placeholder is late-bound here from
#               $SETUP_UB_DEVICE (env.sh probes it per pod via urma_admin)
#   BINARY      mooncake_kvtest path (default: mooncake_kvtest from PATH)
#
# Everything else (MC_* SDK vars, SETUP_*) comes from env.sh (sourced here),
# then env.mooncake.sh (hand-editable tuning panel; same-name vars win). The
# exit code is written to $LOG_FILE.exitrc so the orchestrator can fail the
# scenario when a backgrounded instance dies with an error.

set -u
SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
ENV_FILE="$SCRIPT_DIR/env.sh"

usage() { echo "usage: $0 LOG_FILE CONFIG_JSON [BINARY]" >&2; exit 2; }

[ $# -ge 2 ] || usage
LOG_FILE=$1
CONFIG=$2
BINARY=${3:-mooncake_kvtest}

if [ ! -f "$ENV_FILE" ]; then
  echo "[FATAL] env.sh not found in $SCRIPT_DIR" >&2
  exit 1
fi
source "$ENV_FILE"
# Hand-editable mooncake tuning defaults; sourced AFTER env.sh so same-name
# vars here override the generated env.sh (same rule as the other runners).
[ -f "$SCRIPT_DIR/env.mooncake.sh" ] && source "$SCRIPT_DIR/env.mooncake.sh"

if [ ! -x "$(command -v "$BINARY" 2>/dev/null)" ] && [ ! -x "$BINARY" ]; then
  echo "[FATAL] mooncake_kvtest binary not found or not executable: $BINARY" >&2
  exit 1
fi

mkdir -p "$(dirname "$LOG_FILE")"

# Late-bind the UB device name: every pod discovers its own bonding_dev_*
# via the env.sh urma_admin probe (SETUP_UB_DEVICE). Empty for tcp/rdma
# without an explicit device — same value the Python client would pass.
FINAL_CONFIG="$CONFIG.final.json"
sed "s/__UB_DEVICE__/${SETUP_UB_DEVICE:-}/g" "$CONFIG" > "$FINAL_CONFIG"

# stdout (kvtest narrative) and stderr (C++ glog, FLAGS_logtostderr=1) are
# kept in SEPARATE files, mirroring run_benchmark_pipeline.sh.
"$BINARY" "$FINAL_CONFIG" \
  > "$LOG_FILE" 2> "$LOG_FILE.glog"
rc=$?
# exit-code ledger: the orchestrator reads $LOG_FILE.exitrc after waiting
# for a backgrounded instance — a non-zero rc must FAIL the scenario
echo "$rc" > "$LOG_FILE.exitrc"
exit "$rc"
